    "articleNumberSub": "",
    "displayNumber": "Art. 88",
    "title": "Causales de Despido Justificado atribuibles al Trabajador",
    "content": "El empleador puede dar por terminado el contrato de trabajo despidiendo al trabajador por cualquiera de las causas siguientes: faltas de probidad, violencia, injurias, daños materiales culposos a las maquinarias, revelar secretos de fábrica o inasistencia injustificada durante dos días consecutivos o dos días en un mismo mes.",
    "status": "VIGENTE",
