    "title": "La Dimisión: Terminación Justificada por el Trabajador",
    "content": "Dimisión es la rescisión del contrato de trabajo por voluntad unilateral del trabajador, fundamentada en la comisión de una falta grave cometida por el empleador o sus representantes.",
